<?php require_once __DIR__.'/bootstrap.php'; $stmt=$pdo->prepare('SELECT id,name,category,price,stock FROM products ORDER BY id DESC');$stmt->execute();$products=$stmt->fetchAll();$flash=get_flash();function rupiah(float $number):string{return 'Rp '.number_format($number,0,',','.');} ?>
<!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1.0"><title>MELORA MART — Manajemen Produk</title><link rel="stylesheet" href="assets/style.css"></head><body>
<header class="topbar"><div class="container nav-wrap"><a class="brand" href="index.php">MELORA MART</a><a class="btn btn-primary" href="create.php">+ Tambah Produk</a></div></header>
